// Temporary code-authored paper doll, NOT PixelLab output. Logical 64x64 rig.
// Every layer has an 16px transparent gutter (96x96 raster) for extended weapons.
// Every visual slot has its own canvas. Shared joints keep all clothing attached.
export const SLOTS = {
  hat:{label:'หมวก',choices:[['none','ไม่ใส่'],['hood','ฮู้ดผ้าครีม'],['cap','หมวกพลัม']]},
  shirt:{label:'เสื้อ',choices:[['none','ไม่ใส่'],['moss','เสื้อนักผจญภัย'],['plum','เสื้อพลัม']]},
  pants:{label:'กางเกง',choices:[['none','ไม่ใส่'],['charcoal','กางเกงสีถ่าน'],['sand','กางเกงสีทราย']]},
  weapon:{label:'อาวุธ',choices:[['none','ไม่ใส่'],['sword','ดาบสั้น'],['axe','ขวานเหล็ก']]},
  wrist:{label:'ข้อมือ',choices:[['none','ไม่ใส่'],['bronze','ปลอกข้อมือทองแดง'],['cloth','ผ้าพันข้อมือ']]},
  boots:{label:'รองเท้า',choices:[['none','ไม่ใส่'],['leather','รองเท้าหนัง'],['ivory','รองเท้าสีครีม']]}
};
export const DEFAULT_OUTFIT={hat:'none',shirt:'moss',pants:'charcoal',weapon:'sword',wrist:'bronze',boots:'leather'};
export const ACTIONS={idle:{label:'ยืน',frames:6,duration:1200},walk:{label:'เดิน',frames:8,duration:680},attack:{label:'ตีธรรมดา',frames:8,duration:340,impact:.42,damage:24},slam:{label:'ฟาด',frames:10,duration:570,impact:.57,damage:58},leap:{label:'กระโดดพุ่งโจมตี',frames:12,duration:790,impact:.67,damage:76}};
const C={outline:'#302520',skin:'#f2bb87',skinLight:'#ffdcab',skinShadow:'#d98a5b',hair:'#276361',hairMid:'#397f79',hairLight:'#69a095',cream:'#efe0b8',ivory:'#fff1cc',brown:'#594036',brownLight:'#95603c',gold:'#d6a557'};
const palettes={moss:['#40563e','#78925b','#b0be74'],plum:['#4e344b','#87577b','#b3819b'],charcoal:['#37383a','#56575b','#75777b'],sand:['#725940','#b59368','#d7bf91'],leather:['#393030','#69503c','#98764d'],ivory:['#817452','#c4b48a','#ecdfb9']};
const v=(x,y)=>({x,y}),shift=(a,x,y)=>v(a.x+x,a.y+y);
function point(origin,length,angle){return v(origin.x+Math.cos(angle)*length,origin.y+Math.sin(angle)*length);}
function ease(t){return t*t*(3-2*t);}
function interpolate(keys,t){for(let i=1;i<keys.length;i++){if(t<=keys[i][0]){const a=keys[i-1],b=keys[i],q=ease(Math.max(0,(t-a[0])/(b[0]-a[0])));return a[1]+(b[1]-a[1])*q;}}return keys.at(-1)[1];}
// Angles are joint rotations in radians. Root movement is separate from rig motion.
export function poseFor(mode,t){
  let bob=0,lean=0,frontArm=1.06,backArm=1.95,leg=0,backLeg=0,lift=0,weapon=.28,rootX=0,rootY=0;
  if(mode==='idle')bob=Math.sin(t*Math.PI*2)*.45;
  if(mode==='walk'){const a=Math.sin(t*Math.PI*2);bob=-Math.abs(Math.cos(t*Math.PI*2))*.7;leg=a*4.5;backLeg=-leg;lift=Math.max(0,a)*3;frontArm=1.25-a*.58;backArm=1.8+a*.58;weapon=.35;rootX=0;}
  if(mode==='attack'){frontArm=interpolate([[0,1.06],[.24,-1.95],[.42,-.08],[.67,.85],[1,1.06]],t);weapon=interpolate([[0,.28],[.24,-1.55],[.42,.30],[.67,.92],[1,.28]],t);lean=interpolate([[0,0],[.24,-1],[.42,3],[1,0]],t);rootX=interpolate([[0,0],[.24,-2],[.42,7],[1,0]],t);leg=2;backLeg=-2;}
  if(mode==='slam'){frontArm=interpolate([[0,1.06],[.30,-1.58],[.45,-1.70],[.57,.92],[.77,1.22],[1,1.06]],t);weapon=interpolate([[0,.28],[.3,-1.72],[.45,-1.8],[.57,1.12],[.77,1.28],[1,.28]],t);bob=interpolate([[0,0],[.3,-2],[.57,3],[1,0]],t);rootX=interpolate([[0,0],[.45,-2],[.57,9],[1,0]],t);lean=interpolate([[0,0],[.45,-2],[.57,4],[1,0]],t);leg=3;backLeg=-3;}
  if(mode==='leap'){rootY=interpolate([[0,0],[.14,2],[.38,-22],[.52,-24],[.67,0],[.80,3],[1,0]],t);rootX=interpolate([[0,0],[.14,-3],[.52,17],[.67,25],[1,0]],t);frontArm=interpolate([[0,1.06],[.14,-1.3],[.45,-1.8],[.67,.0],[.8,.8],[1,1.06]],t);weapon=interpolate([[0,.28],[.14,-1.4],[.45,-1.2],[.67,.1],[.8,.8],[1,.28]],t);lean=interpolate([[0,0],[.52,3],[.67,4],[1,0]],t);leg=interpolate([[0,0],[.4,6],[.67,3],[1,0]],t);backLeg=-leg;lift=t>.18&&t<.63?4:0;}
  const shoulder=v(34+lean,35+bob),backShoulder=v(28+lean,35+bob);
  const elbow=point(shoulder,6,frontArm),hand=point(elbow,6,frontArm+.16);
  const backElbow=point(backShoulder,6,backArm),backHand=point(backElbow,6,backArm-.12);
  const hip=v(33,46+bob),backHip=v(28,46+bob),knee=v(33+leg*.45,51-lift*.55),ankle=v(34+leg,57-lift);
  const backKnee=v(28+backLeg*.45,51-(mode==='walk'?Math.max(0,-leg)*.3:lift*.3)),backAnkle=v(28+backLeg,57-(mode==='walk'?Math.max(0,-leg)*.65:lift*.45));
  return {head:v(30+lean*.6,20+bob),torso:v(30+lean*.3,40+bob),shoulder,backShoulder,elbow,hand,backElbow,backHand,hip,backHip,knee,ankle,backKnee,backAnkle,weapon,rootX,rootY};
}
function rasterPoly(ctx,points,color){ctx.fillStyle=color;const low=Math.ceil(Math.min(...points.map(p=>p.y))),high=Math.floor(Math.max(...points.map(p=>p.y)));for(let y=low;y<=high;y++){const xs=[];for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];if((a.y<=y&&b.y>y)||(b.y<=y&&a.y>y))xs.push(a.x+(y-a.y)*(b.x-a.x)/(b.y-a.y));}xs.sort((a,b)=>a-b);for(let j=0;j+1<xs.length;j+=2)ctx.fillRect(Math.ceil(xs[j]),y,Math.max(1,Math.floor(xs[j+1])-Math.ceil(xs[j])+1),1);}}
function box(c,x,y,w,h,color){c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function segment(c,a,b,width,pal){const angle=Math.atan2(b.y-a.y,b.x-a.x),nx=Math.sin(angle),ny=-Math.cos(angle);const poly=w=>[shift(a,nx*w,ny*w),shift(b,nx*w,ny*w),shift(b,-nx*w,-ny*w),shift(a,-nx*w,-ny*w)];rasterPoly(c,poly(width/2+1),C.outline);rasterPoly(c,poly(width/2),pal[1]);rasterPoly(c,[shift(a,nx*width/2,ny*width/2),shift(b,nx*width/2,ny*width/2),shift(b,0,0),shift(a,0,0)],pal[2]);}
function head(c,p){const x=p.x,y=p.y;rasterPoly(c,[v(x-11,y-12),v(x+4,y-12),v(x+12,y-6),v(x+13,y+5),v(x+9,y+11),v(x-4,y+12),v(x-12,y+6),v(x-14,y-3)],C.outline);rasterPoly(c,[v(x-10,y-10),v(x+3,y-10),v(x+10,y-5),v(x+11,y+4),v(x+8,y+10),v(x-3,y+10),v(x-11,y+5),v(x-12,y-3)],C.skin);box(c,x+1,y-5,8,8,C.skinLight);box(c,x+8,y-1,2,4,C.outline);box(c,x+9,y-2,2,2,C.outline);box(c,x+7,y+6,2,1,C.skinShadow);box(c,x+10,y+7,1,1,C.outline);rasterPoly(c,[v(x-14,y-6),v(x-11,y-11),v(x-8,y-13),v(x+3,y-13),v(x+8,y-10),v(x+11,y-6),v(x+10,y-4),v(x+7,y-4),v(x+5,y-7),v(x+4,y-2),v(x,y+2),v(x-1,y-2),v(x-5,y+5),v(x-8,y+3),v(x-9,y+8),v(x-13,y+4)],C.outline);rasterPoly(c,[v(x-13,y-5),v(x-10,y-10),v(x-7,y-12),v(x+2,y-12),v(x+7,y-9),v(x+9,y-6),v(x+6,y-5),v(x+5,y-9),v(x+3,y-3),v(x,y),v(x-1,y-5),v(x-5,y+2),v(x-8,y+1),v(x-10,y+5),v(x-12,y+2)],C.hair);rasterPoly(c,[v(x-10,y-7),v(x-6,y-10),v(x+1,y-10),v(x+4,y-9),v(x,y-6),v(x-5,y-4)],C.hairMid);box(c,x-7,y-9,4,1,C.hairLight);box(c,x-10,y+3,3,3,C.skinShadow);box(c,x-9,y+3,2,2,C.skin);}
function torso(c,p,pal){const x=p.x,y=p.y;rasterPoly(c,[v(x-5,y-8),v(x+5,y-8),v(x+7,y+7),v(x-7,y+7)],C.outline);rasterPoly(c,[v(x-4,y-7),v(x+4,y-7),v(x+6,y+6),v(x-6,y+6)],pal[1]);box(c,x-3,y-5,3,10,pal[2]);box(c,x+3,y-5,2,10,pal[0]);}
function shoe(c,a,pal){rasterPoly(c,[v(a.x-3,a.y-3),v(a.x+2,a.y-3),v(a.x+3,a.y),v(a.x+7,a.y+1),v(a.x+7,a.y+3),v(a.x-3,a.y+3)],C.outline);box(c,a.x-2,a.y-2,4,4,pal[1]);box(c,a.x-2,a.y+1,8,2,pal[1]);box(c,a.x-1,a.y-2,3,1,pal[2]);box(c,a.x-2,a.y+3,9,1,pal[0]);}
function weapon(c,p,type){const a=p.hand,angle=p.weapon;const convert=(x,y)=>v(a.x+Math.cos(angle)*x-Math.sin(angle)*y,a.y+Math.sin(angle)*x+Math.cos(angle)*y);const poly=(ps,col)=>rasterPoly(c,ps.map(q=>convert(...q)),col);poly([[-3,-2],[4,-2],[4,2],[-3,2]],C.outline);poly([[-2,-1],[4,-1],[4,1],[-2,1]],C.brownLight);poly([[3,-4],[5,-4],[5,4],[3,4]],C.outline);poly([[3,-3],[4,-3],[4,3],[3,3]],C.gold);if(type==='sword'){poly([[5,-3],[17,-3],[22,0],[17,3],[5,3]],C.outline);poly([[5,-2],[17,-2],[20,0],[17,2],[5,2]],'#d9ddc8');poly([[6,-2],[16,-2],[18,0],[6,0]],C.ivory);}else{poly([[5,-1],[21,-1],[21,1],[5,1]],C.outline);poly([[5,0],[20,0],[20,1],[5,1]],C.brownLight);poly([[13,-7],[18,-8],[22,-6],[23,-2],[21,4],[17,5],[13,3]],C.outline);poly([[14,-6],[18,-7],[21,-5],[22,-2],[20,3],[17,4],[14,2]],'#869698');poly([[19,-6],[21,-5],[22,-2],[20,3],[19,3]],'#dce6ce');}}
const make=(padded=true)=>{const c=document.createElement('canvas');c.width=c.height=96;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;if(padded)ctx.translate(16,16);return c;};
export class PaperDoll {
  constructor(){this.layers=Object.fromEntries(['body',...Object.keys(SLOTS)].map(k=>[k,make()]));this.frame=make(false);}
  draw(outfit,mode,t){const p=poseFor(mode,t),pal=[C.skinShadow,C.skin,C.skinLight];for(const c of Object.values(this.layers))c.getContext('2d').clearRect(-16,-16,96,96);
    const body=this.layers.body.getContext('2d');segment(body,p.backHip,p.backKnee,4,pal);segment(body,p.backKnee,p.backAnkle,4,pal);shoe(body,p.backAnkle,pal);segment(body,p.backShoulder,p.backElbow,4,pal);segment(body,p.backElbow,p.backHand,3,pal);torso(body,p.torso,pal);box(body,p.torso.x-5,p.torso.y+4,10,3,'#ebdfc4');segment(body,p.hip,p.knee,4,pal);segment(body,p.knee,p.ankle,4,pal);shoe(body,p.ankle,pal);segment(body,p.shoulder,p.elbow,4,pal);segment(body,p.elbow,p.hand,3,pal);head(body,p.head);
    if(outfit.shirt!=='none'){const c=this.layers.shirt.getContext('2d'),s=palettes[outfit.shirt];torso(c,p.torso,s);segment(c,p.backShoulder,shift(p.backElbow,0,-1),5,s);segment(c,p.shoulder,shift(p.elbow,0,-1),5,s);box(c,p.torso.x-6,p.torso.y+4,12,2,'#aa6847');box(c,p.torso.x+2,p.torso.y+4,2,2,C.gold);const x=p.torso.x,y=p.torso.y;rasterPoly(c,[v(x-8,y-9),v(x+6,y-9),v(x+8,y-4),v(x+3,y-2),v(x-8,y-5),v(x-12,y-1)],C.outline);rasterPoly(c,[v(x-7,y-8),v(x+5,y-8),v(x+6,y-4),v(x+2,y-3),v(x-8,y-6),v(x-10,y-2)],outfit.shirt==='moss'?C.cream:'#c2a3b8');}
    if(outfit.pants!=='none'){const c=this.layers.pants.getContext('2d'),s=palettes[outfit.pants];segment(c,p.backHip,p.backKnee,5,s);segment(c,p.backKnee,shift(p.backAnkle,0,-2),4,s);segment(c,p.hip,p.knee,5,s);segment(c,p.knee,shift(p.ankle,0,-2),4,s);box(c,25,p.torso.y+5,13,3,s[1]);}
    if(outfit.boots!=='none'){const c=this.layers.boots.getContext('2d'),s=palettes[outfit.boots];shoe(c,p.backAnkle,s);shoe(c,p.ankle,s);}
    if(outfit.wrist!=='none'){const c=this.layers.wrist.getContext('2d'),s=outfit.wrist==='bronze'?['#725034','#b58449','#e0b96d']:['#92866a','#daccaa','#f3e7c9'];for(const [a,b] of [[p.elbow,p.hand],[p.backElbow,p.backHand]]){const start=v(a.x+(b.x-a.x)*.42,a.y+(b.y-a.y)*.42),end=v(a.x+(b.x-a.x)*.85,a.y+(b.y-a.y)*.85);segment(c,start,end,4,s);}}
    if(outfit.weapon!=='none')weapon(this.layers.weapon.getContext('2d'),p,outfit.weapon);
    if(outfit.hat!=='none'){const c=this.layers.hat.getContext('2d'),x=p.head.x,y=p.head.y;if(outfit.hat==='hood'){rasterPoly(c,[v(x-15,y+8),v(x-15,y-8),v(x-10,y-15),v(x+4,y-15),v(x+11,y-10),v(x+14,y-4),v(x+10,y-4),v(x+5,y-10),v(x-7,y-10),v(x-10,y-5),v(x-9,y+8)],C.outline);rasterPoly(c,[v(x-14,y+6),v(x-14,y-7),v(x-9,y-14),v(x+4,y-14),v(x+10,y-9),v(x+12,y-5),v(x+10,y-5),v(x+5,y-11),v(x-7,y-11),v(x-11,y-5),v(x-10,y+6)],C.cream);box(c,x-8,y-13,11,1,C.ivory);}else{rasterPoly(c,[v(x-13,y-5),v(x-12,y-11),v(x-8,y-16),v(x+5,y-16),v(x+10,y-10),v(x+15,y-7),v(x+15,y-4),v(x-13,y-4)],C.outline);rasterPoly(c,[v(x-12,y-6),v(x-11,y-10),v(x-7,y-15),v(x+4,y-15),v(x+9,y-9),v(x+13,y-7),v(x+13,y-5),v(x-12,y-5)],'#865376');box(c,x-10,y-7,18,2,'#caa570');}}
    const c=this.frame.getContext('2d');c.clearRect(0,0,96,96);for(const key of ['body','pants','boots','shirt','wrist','weapon','hat'])c.drawImage(this.layers[key],0,0);return {image:this.frame,pose:p,layers:this.layers};
  }
}
